Source code in <code>recs/audio/block.py</code> <pre><code>class Blocks[T: Block]:
    def __init__(self, *, blocks: Iterable[T] = (), duration: int = 0) -&gt; None:
        self.blocks = deque(blocks)
        self.duration = duration

    def append(self, block: T) -&gt; None:
        self.blocks.append(block)
        self.duration += len(block)

    def clear(self) -&gt; None:
        self.duration = 0
        self.blocks.clear()

    def clip(self, sample_length: int, from_start: bool) -&gt; Sequence[T]:
        clipped = []
        assert sample_length &gt;= 0
        while self.duration &gt; sample_length:
            index = 0 if from_start else -1
            block = self.blocks[index]
            excess = self.duration - sample_length
            if len(block) &lt;= excess:
                clipped.append(
                    self.blocks.popleft() if from_start else self.blocks.pop()
                )
                self.duration -= len(block)
            else:
                clipped.append(block[:excess] if from_start else block[-excess:])
                self.blocks[index] = block[excess:] if from_start else block[:-excess]
                self.duration = sample_length
        return clipped

    def __getitem__(self, i: int) -&gt; T:
        return self.blocks[i]
</code></pre>

