Source code in <code>recs/audio/channel_writer.py</code> <pre><code>def replay_to(self, replacement: 'ChannelWriter') -&gt; None:
    blocks = list(self._recovery_blocks)
    end = blocks[-1].start_frame + len(blocks[-1]) if blocks else 0
    for block in self._blocks.blocks:
        if block.start_frame + len(block) &gt; end:
            blocks.append(block[max(0, end - block.start_frame) :])
    if not blocks:
        return
    for block in blocks:
        begin = block.start_frame
        end = begin + len(block)
        if (
            replacement.observed_ranges
            and replacement.observed_ranges[-1].end == begin
        ):
            replacement.observed_ranges[-1] = TickRange(
                start=replacement.observed_ranges[-1].start, end=end
            )
        else:
            replacement.observed_ranges.append(TickRange(start=begin, end=end))
        replacement.timeline_frame = end
        replacement.timestamp = (
            block.timestamp + len(block) / self.track.source.samplerate
        )
    replacement._write_blocks(blocks, retain_short=True)
