Source code in <code>recs/audio/playback.py</code> <pre><code>def parse_channels(value: str, label: str) -&gt; tuple[int, ...]:
    try:
        channels = tuple(int(i) for i in value.split('-'))
    except ValueError as error:
        raise RecsError(
            f'{label} must be a channel or adjacent pair: {value}'
        ) from error
    if len(channels) not in {1, 2} or channels[0] &lt; 1:
        raise RecsError(f'{label} must be a positive channel or adjacent pair: {value}')
