Source code in <code>recs/base/times.py</code> <pre><code>def to_time(t: str) -&gt; float:
    parts = t.split(':')
    if not (1 &lt;= len(parts) &lt;= 3):
        raise ValueError('A time can only have three parts')

    s = float(parts.pop())
    if s &lt; 0:
        raise ValueError('TimeSettings cannot be negative')

    if not parts:
        return s

    if s &gt; 59:
        raise ValueError('Seconds cannot be greater than 59')

    m = int(parts.pop())
    if m &lt; 0:
        raise ValueError('Minutes cannot be negative')

    s += 60 * m
    if not parts:
        return s

    if m &gt; 59:
        raise ValueError('Minutes cannot be greater than 59')

    h = int(parts.pop())
    if h &lt; 0:
        raise ValueError('Hours cannot be negative')

    assert not parts
    return s + 3600 * h
</code></pre>

