Source code in <code>recs/cfg/path_pattern.py</code> <pre><code>class PathPattern:
    def __init__(
        self,
        path: str,
        short_file_names: bool = False,
        media_directory: str = '',
    ) -&gt; None:
        self.raw_path = path
        self.media_directory = media_directory
        str_parts = parse_fields(path)
        time_parts = STRFTIME_FIELDS.findall(path)
        parts = set(time_parts + str_parts)

        if bad := parts - FIELDS:
            raise RecsError(f'Unknown: {", ".join(sorted(bad))}')

        self.name_parts = tuple(i for i in str_parts if i not in FIELD_TO_PSTRING)
        self.pstring_parts = tuple(i for i in str_parts if i in FIELD_TO_PSTRING)

        used = set().union(*(FIELD_TO_REQUIRED[p] for p in parts))
        unused = set(Req) - used
        if short_file_names:
            unused.discard(Req.device)

        def rep(r: Req) -&gt; str:
            return (r in unused) * f'{{{r.name}}}'

        y, m, d = rep(Req.year), rep(Req.month), rep(Req.day)
        if (m and not (y or d)) or (not m and (y and d)):
            raise RecsError(f'Must specify year or day with month: {path}')
        date = y + m + d

        h, m, s = rep(Req.hour), rep(Req.minute), rep(Req.second)
        if (m and not (h or s)) or (not m and (h and s)):
            raise RecsError(f'Must specify hour or second with minute: {path}')
        time = h + m + s

        d, c = rep(Req.device), rep(Req.channel)
        dc = '{track}' if all((d, c)) else d + c

        dt = f'{date}-{time}' if all((date, time)) else date + time
        p = f'{dc} + {dt}' if all((dc, dt)) else dc + dt

        self.path = f'{path}/{p}' if all((path, p)) else path + p

        str_parts = parse_fields(self.path)
        self.strf_parts = tuple(i for i in str_parts if i in FIELD_TO_PSTRING)

    def times(self, ts: datetime) -&gt; dict[str, str]:
        return {k: ts.strftime(FIELD_TO_PSTRING[k]) for k in self.strf_parts}

    def make_path(
        self,
        track: track.Track,
        aliases: aliases.Aliases,
        timestamp: float,
        index: int,
    ) -&gt; Path:
        if path := getattr(track.source, 'path', None):
            # It's a file!
            return self._with_media_directory(
                legal_path(Path(self.raw_path) / f'{path.stem}-{index}'),
                timestamp,
            )

        ts = datetime.fromtimestamp(timestamp)
        s = ts.strftime(self.path)
        p = s.format(
            channel=_filename_value(track.name),
            device=_filename_value(aliases.display_name(track.source)),
            index=str(index),
            track=_filename_value(aliases.display_name(track, short=False)),
            **self.times(ts),
        )
        return self._with_media_directory(legal_path(Path(p)), timestamp)

    def make_track_name_path(
        self,
        track_name: str,
        track: track.Track,
        aliases: aliases.Aliases,
        timestamp: float,
        index: int,
    ) -&gt; Path:
        ts = datetime.fromtimestamp(timestamp)
        directory = ts.strftime(self.raw_path).format(
            channel=_filename_value(track.name),
            device=_filename_value(aliases.display_name(track.source)),
            index=str(index),
            track=_filename_value(aliases.display_name(track, short=False)),
            **{k: ts.strftime(v) for k, v in FIELD_TO_PSTRING.items()},
        )
        name = f'{_filename_value(track_name)} + {ts.strftime("%Y%m%d-%H%M%S")}'
        if directory:
            path = legal_path(Path(directory) / name)
        else:
            path = legal_path(Path(name))
        return self._with_media_directory(path, timestamp)

    def _with_media_directory(self, path: Path, timestamp: float) -&gt; Path:
        if not self.media_directory:
            return path
        root = self._media_root(timestamp)
        try:
            relative = path.relative_to(root)
        except ValueError:
            relative = path
        return root / self.media_directory / relative

    def _media_root(self, timestamp: float) -&gt; Path:
        ts = datetime.fromtimestamp(timestamp)
        try:
            return legal_path(Path(ts.strftime(self.raw_path).format(**path_times(ts))))
        except KeyError:
            prefix = self.raw_path.split('{', 1)[0].rstrip('/\\')
            return legal_path(Path(prefix or '.'))
</code></pre>

