Source code in <code>recs/cfg/run_cli.py</code> <pre><code>def cli_overrides(arguments: list[str]) -&gt; set[str]:
    options = {
        '-B': 'band_mode',
        '-b': 'quiet_before_start',
        '-c': 'quiet_after_end',
        '-m': 'metadata',
        '-o': 'output_directory',
        '-R': 'record_everything',
        '-t': 'total_run_time',
        '-z': 'noise_floor',
    }
    fields: set[str] = set()
    for argument in arguments:
        option = argument.split('=', 1)[0]
        if option in options:
            fields.add(options[option])
        elif option.startswith('--'):
            field = option.removeprefix('--no-').removeprefix('--').replace('-', '_')
            if field in FLAT_FIELDS:
                fields.add(field)
    return {f'{FLAT_FIELDS[field]}.{field}' for field in fields}
