Source code in <code>recs/cfg/track.py</code> <pre><code>def source_track(
    d: InputDevice, exc: Sequence[Track] = (), inc: Sequence[Track] = ()
) -&gt; Iterator[Track]:
    if Track(d) in exc:
        return

    excs = [i for i in exc if d.key == i.source.key]
    incs = [i for i in inc if d.key == i.source.key]
    if inc and not incs:
        return

    tracks = [i for i in incs if i.channels]

    ic = {int(c) for t in tracks for c in t.channels} or set(range(1, d.channels + 1))
    ec = {int(c) for t in excs for c in t.channels}

    channels = sorted(ic - ec)

    def track_channel() -&gt; int:
        return tracks[0].channels[-1]

    while channels:
        if tracks:
            found = False
            while channels and track_channel() &gt;= channels[0]:
                channels.pop(0)
                found = True

            if found:
                yield tracks.pop(0)
                continue

            if not channels:
                break

        c1 = channels.pop(0)
        ch = f'{c1}'
        if (
            channels
            and channels[0] == c1 + 1
            and c1 % 2
            and not (tracks and track_channel() == c1 + 1)
        ):
            c2 = channels.pop(0)
            assert c1 + 1 == c2
            ch = f'{c1}-{c2}'

        yield Track(d, ch)

    yield from tracks
</code></pre>

