Source code in <code>recs/edit/output.py</code> <pre><code>def validate_outputs(
    edit: ArrangementScore, graph: EditGraph, destination: Path
) -&gt; None:
    if destination.exists():
        raise RecsError(f'Output session directory already exists: {destination}')
    targets = {d.output: d for d in edit.destinations}
    if len(targets) != len(edit.destinations) or set(targets) != {
        o.name for o in edit.outputs
    }:
        raise RecsError(
            'Final render requires exactly one destination for every output port'
        )
    paths: list[Path] = []
    for port in edit.outputs:
        output = targets[port.name]
        path = destination / output.path
        resolved = path.resolve()
        audio_directory = (destination / 'audio').resolve()
        if not resolved.is_relative_to(audio_directory):
            raise RecsError(
                f'Output {output.output}: path must remain inside audio/: {output.path}'
            )
        if output.path.suffix.lower() != f'.{output.format}':
            raise RecsError(
                f'Output {output.output}: path extension does not match {output.format}'
            )
        if resolved in paths:
            raise RecsError(f'Duplicate output path: {output.path}')
        paths.append(resolved)
        if not isinstance(port.stream, AudioType):
            raise RecsError('audio renderer requires an audio output')
        channels = len(port.stream.channels)
        if output.format == Format.flac and channels &gt; 8:
            raise RecsError(f'Output {output.output}: FLAC supports at most 8 channels')
        if output.format == Format.mp3 and channels &gt; 2:
            raise RecsError(f'Output {output.output}: MP3 supports at most 2 channels')
        if not soundfile.check_format(output.format, output.subtype):
            detail = output.format
            if output.subtype is not None:
                detail += f'/{output.subtype}'
            raise RecsError(f'Output {output.output}: unsupported format {detail}')
