    if (resolver is None) != (resources is None):
        raise ValueError('asset resolver and resources must be supplied together')
    if source.file is not None:
        return _resolve_file_source(source, edit_directory)
    if source.memory is not None:
        raise RecsError(
            f'Source {source.name}: memory source is valid only inside a composition'
        )
    assert source.record is not None
    assert source.selector is not None
    record_path = recording_path(edit_directory / source.record).resolve()
    if document is None and not record_path.is_file():
        raise RecsError(
            f'Source {source.name}: session record does not exist: {record_path}'
        )
    records = (
        [(record_path, document)]
        if document is not None
        else read_recording_chain(record_path)
    )
    selected = [
        (p, d, s)
        for p, d in records
        for s in d.body.streams
        if isinstance(s, AudioStream)
        and (stream_id is None or s.name == stream_id)
        and (s.source_name or s.source_id) == source.selector.source
        and (s.track_name or s.name) == source.selector.track
    ]
    if not selected:
        raise RecsError(
            f'Source {source.name}: selector {source.selector!r} '
            'matches no audio stream'
        )
    if any(s.discontinuities for _, _, s in selected):
        raise RecsError(
            f'Source {source.name}: unknown-duration audio loss '
            'requires explicit alignment'
        )
    if any(s.unmapped_fragments for _, _, s in selected):
        raise RecsError(
            f'Source {source.name}: timeline placement is unresolved; '
            'recorded samples cannot be placed automatically'
        )
    if any(d.body.state != 'sealed' for _, d, _ in selected):
        raise RecsError(f'Source {source.name}: recording is still open')
    widths = {len(s.stream.channels) for _, _, s in selected}
    clocks = [
        t for _, d, s in selected for t in d.timebases if t.name == s.stream.timebase
    ]
    if len({t.name for t in clocks}) != 1:
        raise RecsError(
            f'Source {source.name}: independent capture clocks '
            'require explicit alignment'
        )
    if any(t.rate.denominator != 1 for t in clocks):
        raise RecsError(
            f'Source {source.name}: this renderer requires integer audio sample rates'
        )
    rates = {t.rate.numerator for t in clocks}
    if len(widths) != 1 or len(rates) != 1:
        raise RecsError(f'Source {source.name}: inconsistent audio metadata')
    file_width = next(iter(widths))
    rate = next(iter(rates))
    offset = selected_channels[0] if selected_channels else source.selector.channel
    if offset is not None and offset &gt;= file_width:
        raise RecsError(
            f'Source {source.name}: channel offset {offset} exceeds width {file_width}'
        )
    width = (
        len(selected_channels)
        if selected_channels
        else (1 if offset is not None else file_width)
    )
    variants: dict[
        tuple[int, int], list[tuple[Path, Asset, recording.AudioFragment]]
    ] = {}
    for path, document, stream in selected:
        assets = {a.name: a for a in document.assets}
        for fragment in stream.fragments:
            variants.setdefault(
                (fragment.start, fragment.start + fragment.count), []
            ).append((path, assets[fragment.asset], fragment))
    fragments: list[AudioFragment] = []
    prepared: dict[tuple[Path, str], Path] = {}
    selected_fragments: list[tuple[int, int, Path, Asset, recording.AudioFragment]] = []
    for (start, end), choices in sorted(variants.items()):
        if source.input_format is not None:
            choices = [c for c in choices if c[1].encoding == source.input_format]
        else:
            for encoding in Format:
                if preferred := [c for c in choices if c[1].encoding == encoding]:
                    choices = preferred
                    break
        if len(choices) != 1:
            raise RecsError(
                f'Source {source.name}: ambiguous variants for frames {start}:{end}'
            )
        selected_fragments.append((start, end, *choices[0]))
    acquired = None
    if resolver is not None:
        assert resources is not None
        acquired = resources.enter_context(
            prepare_assets(
                {
                    f'{p}:{a.name}': resolver.open(a, p.parent)
                    for _, _, p, a, _ in selected_fragments
                }
            )
        )
    for start, end, record_file, asset, span in selected_fragments:
        directory = record_file.parent
        if resolver is None:
            relative_path = asset_path(asset)
            path = (directory / relative_path).resolve()
            if not path.is_relative_to(directory.resolve()):
                raise RecsError(f'Asset escapes the session directory: {relative_path}')
            byte_length = asset_content(asset).byte_length
            if byte_length is not None and path.stat().st_size != byte_length:
                raise RecsError(
                    f'Source {source.name}: asset size disagrees with recording: '
                    f'{relative_path}'
                )
            source_path = None
            display_path = relative_path
        else:
            assert resources is not None
            key = record_file, asset.name
            if key not in prepared:
                assert acquired is not None
                prepared[key] = _prepare_asset_path(
                    acquired.streams[f'{record_file}:{asset.name}'], resources
                )
            path = prepared[key]
            source_path = f'{record_file}:{asset.name}'
            display_path = asset.name
        info = soundfile.info(path)
        if (
            info.channels != file_width
            or info.samplerate != rate
            or span.asset_start + span.count &gt; info.frames
        ):
            raise RecsError(
                f'Source {source.name}: file metadata disagrees with recording: '
                f'{display_path}'
            )
        fragments.append(
            AudioFragment(
                path=path,
                source_path=source_path,
                start=start,
                end=end,
                channels=width,
                channel_offset=offset or 0,
                asset_start=span.asset_start,
            )
        )
    if any(a.end &gt; b.start for a, b in zip(fragments, fragments[1:], strict=False)):
        raise RecsError(
            f'Source {source.name}: overlapping source ranges across recordings'
        )
    return ResolvedSource(
        name=source.name,
        record=record_path,
        file=None,
        session_id=records[0][1].name,
        selector=f'{source.selector.source}:{source.selector.track}',
        channels=width,
        sample_rate=rate,
        timeline_end=max(s.end for _, _, s in selected),
        fragments=fragments,
    )
