        if isinstance(files[0], session_record.EventFileRecord):
            if any(
                not isinstance(f, session_record.EventFileRecord)
                or f.timebase != files[0].timebase
                for f in files
            ):
                raise RecsError(f'Event clock changes within {source_id}')
            streams.append(
                EventStream(
