    ) -&gt; None:
        # Pin the profile snapshot before making source-specific configuration copies.
        _ = cfg.device_profiles
        self.cfg = cfg
        self.state = state
        self.session_directory = session_directory
        self.saved_tracks = saved_tracks
        self.track_names = track_names
        self.warning = warning
        self.event = event
        self.file_update = file_update
        self.calibration_update = calibration_update
        self.buffer_update = buffer_update
        self.write_error = write_error
        self.source_process = source_process
        self.device_poller = device_poller
        self.waveform_update = waveform_update
        self.waveforms_enabled = False
        self.runtime_output_directory: Path | None = None
        self.writing_enabled = True
        self.writing_suspended: set[str] = set()
        self.source_processes = {
            source.key: self.source_process(
                cfg, tracks, session_directory, track_names=track_names
            )
            for source, tracks in initial_tracks
        }
        self.hardware_sources = {
            name: source
            for name, source in self.source_processes.items()
            if isinstance(source.source, InputDevice)
        }
        self.file_sources = {
            name: source
            for name, source in self.source_processes.items()
            if isinstance(source.source, FileSource)
        }
        self.source_frames = dict.fromkeys(self.source_processes, 0)
        self.buffer_stats: dict[str, BufferStats] = {}
        self.buffer_report_times: dict[str, float] = {}
        self.buffer_drops_reported = dict.fromkeys(self.source_processes, 0)
        self.buffer_pressure_reported = dict.fromkeys(self.source_processes, 0.0)
        self.source_frames_at_start = dict.fromkeys(self.source_processes, 0)
        self.source_start_times = dict.fromkeys(self.source_processes, state.start_time)
        self.source_last_updates = dict.fromkeys(
            self.source_processes, state.start_time
        )
        self.source_last_progress: dict[str, float] = {}
        self.failed_sources: set[str] = set()
        self.lag_reported: set[str] = set()
        self.present_hardware: set[str] = set()
        self.no_devices_reported = False
        self.no_channels_reported = False
        self.discovery_sequence = -1
        self.discovery_failure_reported = False
        self.poller: DevicePoller | None = None
        if self.hardware_sources or not self.file_sources:
            self.poller = self.device_poller(cfg.console.sleep_time_device)
            self.poller.poll()

    @property
    def sources(self) -&gt; dict[str, SourceProcess]:
        return self.source_processes

    @property
    def hardware(self) -&gt; dict[str, SourceProcess]:
        return self.hardware_sources

    @property
    def files(self) -&gt; dict[str, SourceProcess]:
        return self.file_sources

    @property
    def frames(self) -&gt; dict[str, int]:
        return self.source_frames

    @property
    def failed(self) -&gt; set[str]:
        return self.failed_sources

    @property
    def present(self) -&gt; set[str]:
        return self.present_hardware

    def set_cfg(self, cfg: Cfg, revision: int | None = None) -&gt; None:
        self.cfg = cfg
        for source in self.source_processes.values():
            if source.source.name == cfg.muted_device_name:
                source.stop()
            source.set_cfg(self._source_cfg(cfg), revision=revision)

    def set_runtime_output_directory(self, output_directory: Path | None) -&gt; None:
        self.runtime_output_directory = output_directory
        self.set_cfg(self.cfg)

    def set_session_directory(self, session_directory: Path) -&gt; None:
        self.session_directory = session_directory
        for source in self.source_processes.values():
            source.set_session_directory(session_directory)

    def set_track_names(self, track_names: SourceTrackNames) -&gt; None:
        self.track_names = track_names
        for source in self.source_processes.values():
            source.set_track_names(track_names)

    def set_waveforms_enabled(self, enabled: bool) -&gt; None:
        self.waveforms_enabled = enabled
        for source in self.source_processes.values():
            source.set_waveforms_enabled(enabled)

    def set_writing_enabled(
        self, enabled: bool, recovery_failover: bool = False
    ) -&gt; None:
        self.writing_enabled = enabled
        self.writing_suspended = {
            name
            for name, source in self.source_processes.items()
            if not source.is_alive
        }
        for name, source in self.source_processes.items():
            source.set_writing_enabled(enabled, recovery_failover)
            if enabled:
                self.writing_suspended.discard(name)

    @property
    def writing_is_suspended(self) -&gt; bool:
        return self.writing_suspended &gt;= {
            name for name, source in self.source_processes.items() if source.is_alive
        }

    def poll(self, paused: bool, expired: bool) -&gt; None:
        if self.poller is None:
            return
        status = self.poller.status
        if status.sequence == self.discovery_sequence:
            return
        self.discovery_sequence = status.sequence
        if status.failure is not None:
            if not self.discovery_failure_reported:
                self.warning(
                    f'Device discovery unavailable ({status.failure}); '
                    'keeping current device state'
                )
                self.discovery_failure_reported = True
            return
        if status.health != DiscoveryHealth.healthy or status.devices is None:
            return
        if self.discovery_failure_reported:
            self.warning('Device discovery recovered')
            self.discovery_failure_reported = False
        devices = status.devices
        if muted_name := self.cfg.muted_device_name:
            devices = [i for i in devices if i['name'] != muted_name]
        snapshot = {device_key(i): i for i in devices}
        if snapshot:
            self.no_devices_reported = False
        elif not self.present_hardware and not self.cfg.selection.include:
            self._report_no_devices()
        selected_device_present = self._add_detected_hardware(snapshot)
        compatible: set[str] = set()
        for name, source in self.hardware_sources.items():
            info = snapshot.get(name)
            channels = int(info['max_input_channels']) if info is not None else 0
            # Some backends hide open inputs; progressing capture is stronger evidence.
            if (
                (info is None or channels &lt; source.required_channels)
                and not paused
                and not expired
                and (self.writing_enabled or source.audio is not None)
                and source.source.name != muted_name
                and self.capture_progressing(source)
            ):
                compatible.add(name)
                continue
            if info is None:
                if name in self.present_hardware:
                    self.warning(f'Device {name} went offline')
                self.failed_sources.discard(name)
                source.stop()
                continue
            if channels &lt; source.required_channels:
                source.stop()
                if name not in self.failed_sources:
                    self.warning(
                        f'{name} has {channels} input channels; '
                        f'{source.required_channels} required'
                    )
                    self.failed_sources.add(name)
                continue
            compatible.add(name)
            if name not in self.present_hardware:
                self.failed_sources.discard(name)
            if (
                not source.started
                and name not in self.failed_sources
                and not paused
                and self.writing_enabled
                and not expired
            ):
                source.start()
                self.source_frames_at_start[name] = self.source_frames[name]
                self.source_start_times[name] = times.timestamp()
                self.source_last_updates[name] = self.source_start_times[name]
        self._record_presence(compatible)
        self.present_hardware = compatible
        if snapshot and not self.hardware_sources and selected_device_present:
            self._report_no_channels()

    def reap(self) -&gt; None:
        for name, source in self.source_processes.items():
            if not source.started or (source.is_alive and source.running):
                continue
            expected = not source.running
            if source.is_alive:
                # join drains updates while enforcing the normal shutdown deadline.
                source.join()
            else:
                self._drain(source.connection)
                source.join(timeout=0)
            for update in source.take_updates():
                self.receive_message(update)
            if (
                name in self.hardware_sources
                and not expected
                and name in self.present_hardware
            ):
                self.failed_sources.add(name)

    def stop_stalled(self) -&gt; None:
        now = times.timestamp()
        for name, source in self.source_processes.items():
            if not source.started or not source.is_alive or not source.running:
                continue
            if now - self.source_last_updates[name] &lt;= SOURCE_STALL_TIMEOUT:
                continue
            if self._forwarding_capture_progressing(source):
                continue
            self.warning(f'Device {name} stopped sending updates')
            source.stop()
            source.join()
            if name in self.hardware_sources:
                self.failed_sources.add(name)

    def receive_pending_updates(self) -&gt; None:
        for source in self.source_processes.values():
            for update in source.take_updates():
                self.receive_message(update)

    def receive_connection(self, conn: connection.Connection) -&gt; bool:
        try:
            message = conn.recv()
        except (EOFError, OSError):
            return False
        self.receive_message(cast(SourceUpdate | SourceFailure, message))
        return True

    def receive_message(self, message: SourceUpdate | SourceFailure) -&gt; None:
        if isinstance(message, SourceFailure):
            self.source_processes[message.source_name].marker_position = None
            self.warning(f'Device {message.source_name} failed: {message.message}')
            self.failed_sources.add(message.source_name)
            return
        self._receive_update(message)

    def stop_hardware(self) -&gt; None:
        for source in self.hardware_sources.values():
            source.stop()

    def join_hardware(self) -&gt; None:
        for source in self.hardware_sources.values():
            source.join()

    def _receive_update(self, update: SourceUpdate) -&gt; None:
        self.source_frames[update.source_name] += update.frames
        self._record_buffer_status(update)
        source = self.source_processes[update.source_name]
        if update.write_error is not None or update.writing_enabled is False:
            source.marker_position = None
        elif update.marker_position is not None:
            source.marker_position = update.marker_position
        if update.waveform_layout is not None:
            source.waveform_generation = max(
                getattr(source, 'waveform_generation', 0),
                update.waveform_layout.generation,
            )
        self.file_update(update, source)
        if update.write_error is not None:
            self.write_error(update.source_name, update.write_error)
        if update.writing_enabled is False:
            self.writing_suspended.add(update.source_name)
        if update.calibration is not None:
            self.calibration_update(update.source_name, update.calibration)
        for revision in update.config_revisions_applied or []:
            self.event('cfg_applied', source=update.source_name, value=revision)
        if not update.channels:
            return
        if self.waveform_update is not None:
            self.waveform_update(
                update.waveform_layout,
                update.waveform_batches or [],
            )
        previous = {
            track_name: channel_state.is_active
            for track_name, channel_state in self.state.state[
                update.source_name
            ].items()
        }
        self.state.update({update.source_name: update.channels})
        self._record_track_activity(
            update.source_name,
            previous,
            update.channels,
            update.track_state_frames,
            update.track_state_timestamps,
            default_frame_count=update.frame_count,
            default_timestamp=update.timestamp,
        )
        now = times.timestamp()
        self.source_last_updates[update.source_name] = now
        if update.frames &gt; 0:
            self.source_last_progress[update.source_name] = now
        if source.running and not self._frame_clock_valid(source, now):
            source.stop()
            self.failed_sources.add(update.source_name)
        elif source.running and self._source_time_expired(source):
            source.stop()

    def _add_detected_hardware(self, snapshot: dict[str, DeviceDict]) -&gt; bool:
        if self.cfg.device.devices.name:
            return True
        devices = get_input_devices(list(snapshot.values()), self.cfg.muted_device_name)
        aliases = Aliases(self.cfg.device.alias, devices)
        for source, tracks in input_device_tracks(self.cfg, devices):
            if source.key in self.source_processes:
                continue
            tracks = _restored_tracks(source, tracks, self.saved_tracks)
            self._add_source(source, tracks, aliases)
        return not self.cfg.selection.include or bool(
            aliases.to_tracks(self.cfg.selection.include, allow_missing=True)
        )

    def _add_source(
        self, source: InputDevice, tracks: Sequence[Track], aliases: Aliases
    ) -&gt; None:
        process = self.source_process(
            self._source_cfg(self.cfg),
            tracks,
            self.session_directory,
            track_names=self.track_names,
        )
        process.set_waveforms_enabled(self.waveforms_enabled)
        self.source_processes[source.key] = process
        self.hardware_sources[source.key] = process
        self.source_frames[source.key] = 0
        self.buffer_drops_reported[source.key] = 0
        self.buffer_pressure_reported[source.key] = 0.0
        self.source_frames_at_start[source.key] = 0
        self.source_start_times[source.key] = self.state.start_time
        self.source_last_updates[source.key] = self.state.start_time
        self.state.add_source(source, tracks, aliases)
        self.no_channels_reported = False

    def _report_no_devices(self) -&gt; None:
        if not self.no_devices_reported:
            self.warning('No input devices detected')
            self.no_devices_reported = True

    def _report_no_channels(self) -&gt; None:
        if not self.no_channels_reported:
            self.warning('No channels selected')
            self.no_channels_reported = True

    def _record_presence(self, compatible: set[str]) -&gt; None:
        for name in sorted(compatible - self.present_hardware):
            device = self.hardware_sources[name].source
            self.event(
                'source_online',
                source=name,
                start_frame=self.source_frames_at_start[name],
                channel_count=device.channels,
                sample_rate=device.samplerate,
                clock_id=capture_clock_id(name),
            )
        for name in sorted(self.present_hardware - compatible):
            for track_name, channel_state in self.state.state[name].items():
                if channel_state.is_active:
                    self.event('track_stopped', source=name, track=track_name)
            self.event('source_offline', source=name)

    def _record_buffer_status(self, update: SourceUpdate) -&gt; None:
        if update.buffer_stats is not None:
            stats = update.buffer_stats
            self.buffer_stats[update.source_name] = stats
            now = monotonic()
            last = self.buffer_report_times.get(update.source_name)
            reported = self.buffer_drops_reported.get(update.source_name, 0)
            pressure = self.buffer_pressure_reported.get(update.source_name, 0.0)
            threshold = self.cfg.recording.audio_buffer_seconds * 0.8
            if (
                last is None
                or now - last &gt;= self.cfg.recording.diagnostics_interval_seconds
                or update.capture_complete
                or (stats.dropped_frames and not reported)
                or (pressure &lt; threshold &lt;= stats.max_queued_seconds)
            ):
                self.buffer_update(update.source_name, stats)
                self.buffer_report_times[update.source_name] = now
                self.buffer_drops_reported[update.source_name] = stats.dropped_frames
                self.buffer_pressure_reported[update.source_name] = (
                    stats.max_queued_seconds
                )
        for warning in update.buffer_warnings or []:
            self.warning(warning)

    def capture_progressing(self, source: SourceProcess) -&gt; bool:
        last_progress = self.source_last_progress.get(source.name)
        return (
            source.is_alive
            and bool(source.running)
            and source.name not in self.failed_sources
            and (
                self._forwarding_capture_progressing(source)
                or (
                    self.source_frames[source.name]
                    &gt; self.source_frames_at_start[source.name]
                    and last_progress is not None
                    and times.timestamp() - last_progress &lt;= SOURCE_STALL_TIMEOUT
                )
            )
        )

    def _forwarding_capture_progressing(self, source: SourceProcess) -&gt; bool:
        return (
            source.audio is not None
            and (not self.writing_enabled or source.name in self.writing_suspended)
            and source.audio.capture_progressing(SOURCE_STALL_TIMEOUT)
        )

    def _frame_clock_valid(self, source: SourceProcess, now: float) -&gt; bool:
        if source.name not in self.hardware_sources:
            return True
        elapsed = now - self.source_start_times[source.name]
        if elapsed &lt; FRAME_CLOCK_GRACE:
            return True
        frames = (
            source.audio.counters[audio_forwarding.CAPTURE_FRAME]
            if source.audio is not None
            else self.source_frames[source.name]
            - self.source_frames_at_start[source.name]
        )
        recorded = frames / source.source.samplerate
        if recorded &gt;= elapsed * MIN_FRAME_CLOCK_RATIO:
            return True
        if source.name not in self.lag_reported:
            self.warning(f'Device {source.source.name} lagging behind real time')
            self.lag_reported.add(source.name)
        return False

    def _source_time_expired(self, source: SourceProcess) -&gt; bool:
        total = self.cfg.recording.total_run_time
        return bool(
            total
            and self.source_frames[source.name]
            &gt;= round(total * source.source.samplerate)
        )

    def _record_track_activity(
        self,
        source: str,
        previous: dict[str, bool],
        updates: Mapping[str, object],
        frame_counts: Mapping[str, int] | None,
        timestamps: Mapping[str, float] | None,
        *,
        default_frame_count: int | None,
        default_timestamp: float | None,
    ) -&gt; None:
        for track_name in updates:
            active = self.state.state[source][track_name].is_active
            if active != previous[track_name]:
                self.event(
                    'track_started' if active else 'track_stopped',
                    source=source,
                    track=track_name,
                    frame_count=(frame_counts or {}).get(
                        track_name, default_frame_count
                    ),
                    timestamp=(timestamps or {}).get(track_name, default_timestamp),
                )

    def _source_cfg(self, cfg: Cfg) -&gt; Cfg:
        if self.runtime_output_directory is None:
            return cfg
        directory = cfg.directory.model_copy(
            update={'output_directory': str(self.runtime_output_directory)}
        )
        result = cfg.model_copy(update={'directory': directory})
        result.__dict__.pop('output_path_pattern', None)
        return result

    def _drain(self, conn: connection.Connection) -&gt; None:
        while conn.poll():
            if not self.receive_connection(conn):
